#include <vector>
#include <map>

class stringx {
    char *chars;
    void *buffer;
public:
    stringx();
    stringx(const char *, int = -1);
    ~stringx();
};

struct vector3d { float x, y, z; };
struct vert {};
struct hw_rasta_vert {};
struct wedge {};
struct face {};
struct reduced_face {};
struct material {};
struct po { char data[0x40]; };

typedef unsigned short vert_ref;
typedef unsigned short wedge_ref;
typedef short material_ref;
typedef unsigned int face_ref;
typedef int visrep_t;

enum { VISREP_PMESH = 0 };

class visual_rep {
public:
    visual_rep(visrep_t, bool = true);
    virtual ~visual_rep();
private:
    char fields[0x10];
};

class vr_pmesh : public visual_rep {
public:
    typedef std::map<material_ref, face_ref> material_map;
    struct bone { stringx name; po pivot; };

    vr_pmesh(const char *, unsigned);
    virtual ~vr_pmesh();

private:
    void _construct(const stringx &, unsigned);

    std::vector<vert> *verts;
    hw_rasta_vert *xverts;
    wedge *wedges;
    int min_faces;
    int *xverts_for_lod;
    int num_wedges;
    face *faces;
    reduced_face *reduced_faces;
    int num_faces;
    std::vector<material *> materials;
    vert_ref *vert_refs_for_wedge_ref;
    wedge_ref *wedge_index_list;
    short *wedge_lod_starts;
    face_ref *original_face_for_face_slot;
    material_map material_changes;
    std::vector<bone> bones;
    bool has_translucent_verts;
    bool progressive;
    int uvanim_update_frame;
    vector3d center;
    float radius;
    vector3d pivot;
    int pivot_valid;
    stringx filename;
    unsigned mesh_flags;
    int max_detail;
    int min_detail;
};

vr_pmesh::vr_pmesh(const char * pmesh_filename, unsigned _mesh_flags ) : visual_rep( VISREP_PMESH )
{
#if defined(TARGET_PC) || XBOX_USE_PMESH_STUFF
  optimized_verts = NULL;
#endif
  _construct(stringx(pmesh_filename), _mesh_flags);
}
